import{_ as a,o as n,c as t,a2 as r}from"./chunks/framework.BXzK3EA4.js";const o="/assets/Rmoney9.DYa1Q6ic.png",s="/assets/Rmoney4%20(1).BPIaaiiT.png",i="/assets/Rmoney7.Bl3mJMxh.png",b=JSON.parse('{"title":"RMoney (XTS)","description":"","frontmatter":{},"headers":[],"relativePath":"connect-brokers/brokers/rmoney.md","filePath":"connect-brokers/brokers/rmoney.md"}'),p={name:"connect-brokers/brokers/rmoney.md"};function l(d,e,c,h,g,u){return n(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="rmoney-xts" tabindex="-1">RMoney (XTS) <a class="header-anchor" href="#rmoney-xts" aria-label="Permalink to &quot;RMoney (XTS)&quot;">​</a></h1><h3 id="rmoney-raghunandan-capital-pvt-ltd-broker-integration" tabindex="-1">RMoney - (Raghunandan Capital Pvt Ltd) Broker Integration <a class="header-anchor" href="#rmoney-raghunandan-capital-pvt-ltd-broker-integration" aria-label="Permalink to &quot;RMoney - (Raghunandan Capital Pvt Ltd) Broker Integration&quot;">​</a></h3><p>RMoney is a Gandhinagar(Gujarat)-based deep discount broker that provides API access via the XTS (Symphony Fintech) platform. This guide will help you integrate RMoney with Tradeboard.</p><h4 id="step-1-create-api-applications" tabindex="-1"><strong>Step 1: Create API Applications</strong> <a class="header-anchor" href="#step-1-create-api-applications" aria-label="Permalink to &quot;**Step 1: Create API Applications**&quot;">​</a></h4><p> Login to <a href="https://xts.rmoneyindia.co.in:3000/dashboard#!/login" target="_blank" rel="noreferrer">https://xts.rmoneyindia.co.in:3000/dashboard#!/login</a></p><figure><img src="'+o+'" alt=""><figcaption></figcaption></figure><p>Once logged in:</p><ol><li>Go to <code>My App</code> &gt; <code>Create New Application</code></li><li>Create two separate apps:</li></ol><ul><li><strong>Interactive Order API</strong></li><li><strong>Market Data API</strong></li></ul><figure><img src="'+s+'" alt=""><figcaption></figcaption></figure><p><strong>Details to Fill:</strong></p><ul><li><strong>App Name</strong>: Tradeboard</li><li><strong>App Description</strong>: Tradeboard</li><li><strong>Redirect URL: (leave it empty)</strong></li><li><strong>Company Name</strong>: Tradeboard (or your own)</li><li>Choose the correct <strong>API Package</strong> depending on the app (Order or Market Data).</li></ul><figure><img src="'+i+`" alt=""><figcaption></figcaption></figure><h4 id="step-2-setup-environment-variables" tabindex="-1">Step 2: Setup Environment Variables <a class="header-anchor" href="#step-2-setup-environment-variables" aria-label="Permalink to &quot;Step 2: Setup Environment Variables&quot;">​</a></h4><p>Refer to the <code>.sample.env</code> file in your Tradeboard folder and prepare your <code>.env</code> as follows:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Broker Configuration</span></span>
<span class="line"><span>BROKER_API_KEY = &#39;YOUR_BROKER_ORDER_API_KEY&#39;</span></span>
<span class="line"><span>BROKER_API_SECRET = &#39;YOUR_ORDER_API_SECRET&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>BROKER_API_KEY_MARKET = &#39;YOUR_BROKER_MARKET_API_KEY&#39;</span></span>
<span class="line"><span>BROKER_API_SECRET_MARKET = &#39;YOUR_BROKER_MARKET_API_SECRET&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>REDIRECT_URL = &#39;http://127.0.0.1:5000/rmoney/callback&#39;</span></span></code></pre></div><p>Replace the values with actual credentials shown on your developer dashboard once approved.</p><h4 id="step-3-start-tradeboard" tabindex="-1"><strong>Step 3: Start Tradeboard</strong> <a class="header-anchor" href="#step-3-start-tradeboard" aria-label="Permalink to &quot;**Step 3: Start Tradeboard**&quot;">​</a></h4><p>Once all environment variables are set and your apps are Active, you can now start Tradeboard.</p><p>Ensure you have installed dependencies and set up the broker configuration properly. Tradeboard will now be able to place orders and fetch market data through RMoney&#39;s XTS API.</p><p>This completes the integration process for RMoney broker with Tradeboard.</p><p>Integrating Tradeboard with RMoney’s XTS API empowers traders and developers to automate and streamline their trading workflows with precision and speed. Users can build robust trading systems capable of reacting to market conditions in real time. Always ensure secure handling of API credentials, implement proper error handling, and monitor your integration to maintain reliability and compliance.</p><h3 id="supported-exchanges" tabindex="-1">Supported Exchanges <a class="header-anchor" href="#supported-exchanges" aria-label="Permalink to &quot;Supported Exchanges&quot;">​</a></h3><p>Tradeboard reads this plugin&#39;s exchange list from <code>broker/rmoney/plugin.json</code> and serves it to the app, so symbol search, the Strategy Builder and the tools pages only offer what the plugin actually handles.</p><ul><li><strong>Tradable:</strong> <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code></li><li><strong>Index feeds:</strong> <code>NSE_INDEX</code>, <code>BSE_INDEX</code></li></ul>`,25)])])}const _=a(p,[["render",l]]);export{b as __pageData,_ as default};
